"""Targeted read-only facts contract with immutable real Git objects, local fixtures only."""
import copy,importlib.util,json,pathlib,unittest
from unittest import mock
ROOT=pathlib.Path('/workspace/work/adopt2121-20261008')
s=importlib.util.spec_from_file_location('facts',ROOT/'snapshot-facts.py');reader=importlib.util.module_from_spec(s);s.loader.exec_module(reader)

class FactsContract(unittest.TestCase):
    def evaluate(self,name='gpc',mutation=None):
        prep=reader.common.read(ROOT/(name+'-adapter/preparation.json'))
        finish=reader.common.read(ROOT/(name+'-adapter/finish-receipt.json'))
        req=reader.common.read(ROOT/(name+'-adapter/start-request.json'))
        original_git=reader.common.git
        lease=json.loads(original_git(req['repo_root'],'show',finish['lease_revision']+':lease.json'))
        fixture={'head':prep['candidate'],'lease':lease,'watchdog':{'repository':req['lease_repository'],'source_ref':req['lease_source_ref'],
                 'is_enabled':False,'last_run_at_utc':None,'observed_at_utc':reader.common.now(),'source':'actual automations.peek receipt'}}
        if mutation:mutation(fixture)
        def git(repo,*args):
            if args[0]=='ls-remote':return fixture['head']+'\t'+args[-1]
            if args[0]=='fetch':return ''
            return original_git(repo,*args)
        class StoreFixture:
            def __init__(self,*args):pass
            def read(self):return finish['lease_revision'],copy.deepcopy(fixture['lease'])
        with mock.patch.object(reader.common,'git',git),mock.patch.object(reader,'GitLeaseStore',StoreFixture):
            return reader.facts(name,fixture['watchdog'])
    def test_all_three_real_checkpoint_and_package_objects(self):
        for name in ['gpc','switcher','gad']:
            facts=self.evaluate(name)
            self.assertTrue(facts['convergence_vector']['integrated'])
            self.assertFalse(facts['snapshot']['watchdog']['enabled'])
            self.assertIsNone(facts['snapshot']['progress']['last_meaningful_progress_at_utc'])
            self.assertEqual(facts['snapshot']['progress']['phase'],facts['product_checkpoint']['phase'])
            self.assertFalse(facts['convergence_vector']['authorizes_product_write'])
    def test_live_owner_guard_and_changed_source_fail_closed(self):
        for mutate in [lambda x:x['lease'].update(owner_id='live'),lambda x:x['lease'].update(external_guard={'state':'running'}),lambda x:x.update(head='a'*40)]:
            with self.assertRaises(AssertionError):self.evaluate(mutation=mutate)
    def test_enabled_stale_or_misbinding_watchdog_rejected(self):
        for mutate in [lambda x:x['watchdog'].update(is_enabled=True),lambda x:x['watchdog'].update(observed_at_utc='2020-01-01T00:00:00Z'),lambda x:x['watchdog'].update(source_ref='refs/heads/wrong')]:
            with self.assertRaises(AssertionError):self.evaluate(mutation=mutate)

if __name__=='__main__':unittest.main(verbosity=2)
